// The bundled canonical skills tree this client ships, and the anchor that
// makes an installed package's own skills trusted with no hosted call and no
// per-machine approval (foo-open-source-transition-v0 T-003, R-001): the npm
// tarball carries skills/ and its registry integrity binds the install, and
// this anchor — the digest of that tree, regenerated by
// `node scripts/skill-tree-anchor.mjs` after any review that changes skills/ —
// binds the bytes at every read. A tree edited after packaging mismatches the
// anchor and is refused, never executed; the drift test
// (test/skillTreeAnchor.test.ts) fails a build that ships a stale anchor.
export const BUNDLED_SKILL_TREE_DOMAIN = "foo.bundled-skill-tree.v1";

export interface BundledSkillTreeAnchor {
  /** Top-level canonical skill folders the package ships. */
  skill_count: number;
  /** foo.bundled-skill-tree.v1 digest over the shipped tree. */
  tree_sha256: string;
}

export const BUNDLED_SKILL_TREE: BundledSkillTreeAnchor = Object.freeze({
  // ==== skill-tree-anchor:generated (scripts/skill-tree-anchor.mjs) ====
  skill_count: 65,
  tree_sha256: "aa4cc26b6363c639ff3d08d4b7c7bf1305159aa88d4743d0444c42af62255e95",
    // ==== end skill-tree-anchor:generated ====
});
